code.en:
# description logic: a concept as a set; intersection = conjunction
birds = {"robin", "penguin", "eagle"}
can_fly = {"robin", "eagle", "plane"}
print(sorted(birds & can_fly))

code.es:
# logica descriptiva: un concepto como conjunto; interseccion = conjuncion
birds = {"robin", "penguin", "eagle"}
can_fly = {"robin", "eagle", "plane"}
print(sorted(birds & can_fly))
